import time

from taf.internal.gnb.oam.coam.vdu.client.cp_config_licensed.v1 import (
    ApiClient,
    CellGroupsResetApi,
    CellResetApi,
    Configuration,
    DiagnosticApi,
    InlineObject,
    InlineObject1,
    StatusApi,
    ApiException
)

from taf.gnb.oam.coam.vdu.exceptions import APINotImplemented, TimeoutException
from taf.gnb.oam.coam.vdu.services.cp_config_licensed.http_client import (
    CPConfigLicensedV1HttpClient,
)
from taf.gnb.oam.coam.vdu.utilities.logger import log_request_response
from taf.gnb.oam.coam.vdu.utilities.m2m_interface_availability_checker import (
    m2m_interface_availability_check,
)
from taf.gnb.oam.coam.vdu.utilities.poll_status import poll_status
from taf.gnb.oam.coam.vdu.utilities.token_provider import auto_token_refresh
from taf.gnb.oam.coam.vdu.utilities.token_storage import TokenStorage
from taf.gnb.oam.coam.vdu.services.sec.sec_v1 import SECv1
from taf.gnb.oam.coam.vdu.services.sec.sec_licensed_v1 import SECLicensedv1


@auto_token_refresh(api_exception=ApiException)
class CPCONFIGLICENSEDv1:
    def __init__(self, con_details):
        self.con_details = con_details
        self.token_storage = TokenStorage(connection_name=con_details.alias)
        self.sec = SECLicensedv1.get_instance(connection_name=con_details.alias) \
            if con_details.use_m2m else SECv1.get_instance(connection_name=con_details.alias)

        conf = Configuration()
        conf.verify_ssl = False
        conf.host = con_details.get_api_client_configuration(original_endpoint=conf.host)
        self.configuration = conf

        api_client = ApiClient(configuration=conf)
        api_client.request = log_request_response(api_client.request)

        self.diagnostic = DiagnosticApi(api_client)
        self.cp_config_status_api = StatusApi(api_client)
        self.cell_group_reset = CellGroupsResetApi(api_client)
        self.cell_reset_api = CellResetApi(api_client)
        self.local_client = CPConfigLicensedV1HttpClient(base_url=con_details.base_url,
                                                         connection_alias=con_details.alias)

    @m2m_interface_availability_check
    def reset_vdu(self, timeout=60, graceful_cell_shutdown=False):
        return self.local_client.reset_vdu(timeout=timeout, graceful_cell_shutdown=graceful_cell_shutdown)

    @m2m_interface_availability_check
    def get_reset_vdu_operation_status(self, operation_id, timeout=30):
        return self.local_client.get_reset_vdu_operation_status(operation_id=operation_id, timeout=timeout)

    @m2m_interface_availability_check
    def block_cell(self, cell_id, timeout=60):
        return self.local_client.block_cell(cell_id=cell_id, timeout=timeout)

    @m2m_interface_availability_check
    def get_block(self, operation_id, timeout=60):
        return self.cp_config_status_api.get_block(operation_id=operation_id,
                                                   _request_timeout=timeout)

    @m2m_interface_availability_check
    def unblock_cell(self, cell_id, timeout=60):
        return self.local_client.unblock_cell(cell_id=cell_id, timeout=timeout)

    @m2m_interface_availability_check
    def get_unblock(self, operation_id, timeout=60):
        return self.cp_config_status_api.get_unblock(operation_id=operation_id, _request_timeout=timeout)

    @m2m_interface_availability_check
    def get_cell_mapping_info_by_nr_cell_dn(self, nr_cell_dn, timeout=60):
        return self.cp_config_status_api.cell_mapping_info_nr_cell_dn_get(nr_cell_dn=nr_cell_dn,
                                                                          _request_timeout=timeout)

    @m2m_interface_availability_check
    def delete_block(self, operation_id, timeout=60):
        self.local_client.delete_block(operation_id=operation_id, timeout=timeout)

    @m2m_interface_availability_check
    def delete_unblock(self, operation_id, timeout=60):
        return self.cp_config_status_api.delete_unblock(operation_id=operation_id,
                                                        _request_timeout=timeout)

    @m2m_interface_availability_check
    def start_rf_diagnostic_test(self, nr_cell_id=-1, act_remote_rf_diag=True, rx_antenna_rssi_high_threshold=-30,
                                 rx_antenna_rssi_low_threshold=-110, tx_antenna_vswr_high_threshold=3,
                                 rx_antenna_rtwp_high_threshold=0, rx_antenna_rtwp_low_threshold=0,
                                 timeout=60):

        operation = self.local_client.start_rf_diagnostic_test(nr_cell_id=nr_cell_id,
                                                               act_remote_rf_diag=act_remote_rf_diag,
                                                               rx_antenna_rssi_high_threshold=rx_antenna_rssi_high_threshold,
                                                               rx_antenna_rssi_low_threshold=rx_antenna_rssi_low_threshold,
                                                               tx_antenna_vswr_high_threshold=tx_antenna_vswr_high_threshold,
                                                               rx_antenna_rtwp_high_threshold=rx_antenna_rtwp_high_threshold,
                                                               rx_antenna_rtwp_low_threshold=rx_antenna_rtwp_low_threshold)

        poll_status(instance=self.local_client,
                    method_name='get_status_of_start_rf_diagnostic_test_operation',
                    operation_id=operation["operationId"], timeout=timeout)

    def get_status_of_start_rf_diagnostic_test_operation(self, operation_id, timeout=30):
        return self.local_client.get_status_of_start_rf_diagnostic_test_operation(operation_id=operation_id,
                                                                                  timeout=timeout)

    @m2m_interface_availability_check
    def get_diagnostic_rf_diagnostic_test_results(self, timeout=30):
        return self.local_client.get_diagnostic_rf_diagnostic_test_results(timeout=timeout)

    @m2m_interface_availability_check
    def remove_uplane_trace_stream(self, trace_id, timeout=30):
        raise APINotImplemented("Uplane tracing has been moved from CP-CONFIG to ASM."
                                "Please connect_to vDU with a version higher than or equal to cuoam_24r2")

    @m2m_interface_availability_check
    def start_uplane_trace_stream(self, trace_type, target_component, nr_cell_dn_list, timeout=30):
        raise APINotImplemented("Uplane tracing has been moved from CP-CONFIG to ASM."
                                "Please connect_to vDU with a version higher than or equal to cuoam_24r2")

    @m2m_interface_availability_check
    def get_active_trace_streams(self, timeout=30):
        raise APINotImplemented("Uplane tracing has been moved from CP-CONFIG to ASM."
                                "Please connect_to vDU with a version higher than or equal to cuoam_24r2")

    @m2m_interface_availability_check
    def stop_uplane_trace_stream(self, trace_id, timeout=30):
        raise APINotImplemented("Uplane tracing has been moved from CP-CONFIG to ASM."
                                "Please connect_to vDU with a version higher than or equal to cuoam_24r2")

    @m2m_interface_availability_check
    def get_traces_activation_status(self, timeout=30):
        raise APINotImplemented("Uplane tracing has been moved from CP-CONFIG to ASM."
                                "Please connect_to vDU with a version higher than or equal to cuoam_24r2")

    @m2m_interface_availability_check
    def trigger_cell_groups_reset(self, dist_name, graceful_cell_shutdown=False, timeout=30):
        inline_object = InlineObject1(dn=dist_name, graceful_cell_shutdown=graceful_cell_shutdown)
        return self.cell_group_reset.cell_groups_operations_resets_post(inline_object1=inline_object,
                                                                        _request_timeout=timeout)

    @m2m_interface_availability_check
    def get_operation_of_reset_cell_group(self, operation_id, timeout=30):
        return self.local_client.get_operation_of_reset_cell_group(operation_id=operation_id, timeout=timeout)

    @m2m_interface_availability_check
    def delete_operation_of_reset_cell_group(self, operation_id, timeout=30):
        return self.cell_group_reset.cell_groups_operations_resets_operation_id_delete(operation_id=operation_id,
                                                                                       _request_timeout=timeout)

    @m2m_interface_availability_check
    def reset_cells(self, dist_name, graceful_cell_shutdown=False, timeout=90):
        inline_object = InlineObject(dist_name=dist_name, graceful_cell_shutdown=graceful_cell_shutdown)
        start_time = time.time()
        info = self.cell_reset_api.cells_operations_resets_post(inline_object=inline_object, _request_timeout=timeout)
        operation_id = info.id
        request_time = time.time() - start_time
        timeout -= request_time
        start_time_of_loop = current_time = time.time()
        while current_time - start_time_of_loop < timeout:
            status_info = self.cell_reset_api.cells_operations_resets_operation_id_get(
                operation_id=operation_id, _request_timeout=timeout)
            if status_info.status == 'ongoing':
                time.sleep(0.2)
                current_time = time.time()
            else:
                self.cell_reset_api.cells_operations_resets_operation_id_delete(
                    operation_id=operation_id, _request_timeout=timeout)
                return status_info.status
        raise TimeoutException("Operation timeout exceeded.")
